import sys
import xml.etree.ElementTree as ET
import json
import os

def parse_config(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        if root.tag != 'report':
            return None
        if 'title' not in root.attrib:
            return None
        title = root.attrib['title']
        rows = []
        for row in root.findall('row'):
            if 'label' not in row.attrib or 'amount' not in row.attrib:
                return None
            rows.append({
                'label': row.attrib['label'],
                'amount': float(row.attrib['amount'])
            })
        return {'title': title, 'rows': rows}
    except (ET.ParseError, IOError) as e:
        return None

def generate_html(rows):
    html = ['''<html>
<head>
    <title>{}</title>
</head>
<body>
    <table>'''.format(rows['title'])]

    html.append('<tr><th>Label</th><th>Amount</th></tr>')

    for row in rows['rows']:
        html.append('<tr><td>{}</td><td>{:.2f}</td></tr>'.format(row['label'], row['amount']))

    html.append('''</table>
</body>
</html>''')
    return '\n'.join(html)

def main():
    if len(sys.argv) != 2:
        print('error: missing config file', file=sys.stderr)
        sys.exit(1)

    xml_file = sys.argv[1]
    config_data = parse_config(xml_file)

    if config_data is None:
        print('error: invalid config file', file=sys.stderr)
        sys.exit(1)

    # Generate HTML
    html_output = generate_html(config_data)
    print(html_output)

    # Generate JSON
    json_file = xml_file.rsplit('.', 1)[0] + '.json'
    with open(json_file, 'w') as f:
        json.dump(config_data, f, indent=2)

if __name__ == '__main__':
    main()
